/**
 * Customer-facing translations for the storefront, cart, order page,
 * and the WhatsApp order message format generated by the API.
 *
 * The merchant chooses a default in their store Settings (tenant.language).
 * Customers can override on the storefront via a flag picker; their choice
 * is persisted in localStorage.
 *
 * Conventions:
 *   - Every locale must have every key. TypeScript enforces this via
 *     Dictionary = typeof dictionaries.en.
 *   - Keep keys English even for non-English locales.
 *   - For RTL locales (Arabic), wrap text without unicode bidi markers —
 *     CSS `dir="rtl"` handles direction.
 */

export type Locale = 'en' | 'es' | 'fr' | 'ar' | 'pt' | 'id';

// RTL languages
export const RTL_LOCALES: Locale[] = ['ar'];
export const isRTL = (locale: Locale) => RTL_LOCALES.includes(locale);

export const SUPPORTED_LOCALES: { code: Locale; label: string; flag: string }[] = [
    // Using ISO 639 codes instead of flag emojis: Windows lacks the
    // regional-indicator-emoji font fallback, so 🇺🇸 renders as "US"
    // rather than a flag. Plain codes look the same everywhere.
    { code: 'en', label: 'English',    flag: 'EN' },
    { code: 'es', label: 'Español',    flag: 'ES' },
    { code: 'pt', label: 'Português',  flag: 'PT' },
    { code: 'fr', label: 'Français',   flag: 'FR' },
    { code: 'ar', label: 'العربية',     flag: 'AR' },
    { code: 'id', label: 'Indonesia',  flag: 'ID' },
];

